import{_ as a,a0 as p,w as o,s as d,ao as r,I as t,x as l,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"完善的 API 的 4 個基本特徵 | LCTT x X-CMD","titleTemplate":false,"description":"完善的 API 的 4 個基本特徵 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"完善的 API 的 4 個基本特徵 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"完善的 API 的 4 個基本特徵 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210518 4 essential characteristics of successful APIs","title":"完善的 API 的 4 個基本特徵","tag":"202106","desc":""},"relativePath":"202106/20210518 4 essential characteristics of successful APIs.md","filePath":"[post].md"}'),u={name:"202106/20210518 4 essential characteristics of successful APIs.md"};function P(f,s,A,m,I,T){const n=p("Link");return o(),d("div",null,[s[60]||(s[60]=r('<h1 id="完善的-api-的-4-個基本特徵" tabindex="-1">完善的 API 的 4 個基本特徵 <a class="header-anchor" href="#完善的-api-的-4-個基本特徵" aria-label="Permalink to “完善的 API 的 4 個基本特徵”">​</a></h1><blockquote><p>創建一個 API（應用程序接口），我們所要做的遠遠不止是讓它能“正常工作”。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/14/155547zs3mffismifqqi59.jpg" alt=""></p><p>如果你正在構建基於 C/S 模型的應用程序，那麼你需要一個應用程序接口（API）。API 就是一種非常清晰而又明確的定義，它是一個<ruby>進程<rt>process</rt></ruby>與另一個進程之間明確定義的邊界。Web 應用中我們常見的邊界定義就是 REST/JSON API。</p><p>雖然很多開發者可能主要關注在如何讓 API 正常工作（或功能正常），但卻還有一些“非功能性”的要求也是需要他們注意的。所有的 API <em>必須具備</em> 的 4 個非功能性的要求是：</p><ul><li>安全</li><li>文檔</li><li>驗證</li><li>測試</li></ul><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><p>在軟件開發中，安全是最基本的要求。對於 API 開發者來説，API 的安全性主要包含以下 4 個方面：</p><ol><li>HTTPS/SSL 證書</li><li>跨域資源共享</li><li>身份認證與 JSON Web 令牌</li><li>授權與作用域</li></ol><h4 id="_1、https-ssl-證書" tabindex="-1">1、HTTPS/SSL 證書 <a class="header-anchor" href="#_1、https-ssl-證書" aria-label="Permalink to “1、HTTPS/SSL 證書”">​</a></h4>',10)),t("p",null,[s[1]||(s[1]=l("Web 應用的黃金標準是使用 SSL 證書的 HTTPS 協議。",-1)),e(n,{href:"https://letsencrypt.org/"},{default:i(()=>[...s[0]||(s[0]=[l("Let's Encrypt",-1)])]),_:1}),s[2]||(s[2]=l(" 可以幫你達到這一目的。Let's Encrypt 來自於非營利性的互聯網安全研究小組（ISRG），它是一個免費的、自動化的、開放的證書頒發機構。",-1))]),s[61]||(s[61]=t("p",null,"Let's Encrypt 的軟件會為你的域（LCTT 譯註：包含域名、IP 等信息）生成中央授權證書。而正是這些證書確保了從你的 API 到客户端的數據載荷是點對點加密的。",-1)),t("p",null,[s[4]||(s[4]=l("Let's Encrypt 支持證書管理的多種部署方案。我們可以通過查看 ",-1)),e(n,{href:"https://letsencrypt.org/docs/"},{default:i(()=>[...s[3]||(s[3]=[l("文檔",-1)])]),_:1}),s[5]||(s[5]=l(" 來找出最適合自己需要的方案。",-1))]),s[62]||(s[62]=t("h4",{id:"_2、跨域資源共享",tabindex:"-1"},[l("2、跨域資源共享 "),t("a",{class:"header-anchor",href:"#_2、跨域資源共享","aria-label":"Permalink to “2、跨域資源共享”"},"​")],-1)),s[63]||(s[63]=t("p",null,[t("ruby",null,[l("跨域資源共享"),t("rt",null,"Cross-origin resource sharing")]),l("（CORS）是一個針對瀏覽器的安全策略預檢。如果你的 API 服務器與發出請求的客户端不在同一個域中，那麼你就要處理 CORS。例如，如果你的服務器運行在 "),t("code",null,"api.domain-a.com"),l(" 並且接到一個來自 "),t("code",null,"domain-b.com"),l(" 的客户端的請求，那麼 CORS 就會（讓瀏覽器）發送一個 HTTP 預檢請求，以便查看你的 API 服務是否會接受來自此客户域的客户端請求。")],-1)),t("p",null,[e(n,{href:"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS"},{default:i(()=>[...s[6]||(s[6]=[l("來自 MDN 的定義",-1)])]),_:1}),s[7]||(s[7]=l("：",-1))]),s[64]||(s[64]=t("blockquote",null,[t("p",null,"“跨域資源共享（CORS）是一種基於 HTTP 頭的機制，這種機制允許服務器標記除自身源外的其他任何來源（域、方案或端口）。而對於這些被服務器標識的源，瀏覽器應該允許我們從它們加載資源。”")],-1)),s[65]||(s[65]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/uploads/cors_principle_1.png",alt:"CORS 原理",title:"CORS principles"})],-1)),t("p",null,[t("em",null,[s[10]||(s[10]=l("(",-1)),e(n,{href:"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS"},{default:i(()=>[...s[8]||(s[8]=[l("MDN文檔",-1)])]),_:1}),s[11]||(s[11]=l("， ",-1)),e(n,{href:"https://creativecommons.org/licenses/by-sa/2.5/"},{default:i(()=>[...s[9]||(s[9]=[l("CC-BY-SA 2.5",-1)])]),_:1}),s[12]||(s[12]=l(")",-1))])]),t("p",null,[s[15]||(s[15]=l("另外，有很多用於 ",-1)),e(n,{href:"https://nodejs.org"},{default:i(()=>[...s[13]||(s[13]=[l("Node.js",-1)])]),_:1}),s[16]||(s[16]=l(" 的輔助庫來 ",-1)),e(n,{href:"https://www.npmjs.com/search?q=CORS"},{default:i(()=>[...s[14]||(s[14]=[l("幫助 API 開發者處理 CORS",-1)])]),_:1}),s[17]||(s[17]=l("。",-1))]),s[66]||(s[66]=t("h4",{id:"_3、身份認證與-json-web-令牌",tabindex:"-1"},[l("3、身份認證與 JSON Web 令牌 "),t("a",{class:"header-anchor",href:"#_3、身份認證與-json-web-令牌","aria-label":"Permalink to “3、身份認證與 JSON Web 令牌”"},"​")],-1)),s[67]||(s[67]=t("p",null,"有多種方法可以驗證你的 API 中的認證用户，但最好的方法之一是使用 JSON Web 令牌（JWT），而這些令牌使用各種知名的加密庫進行簽名。",-1)),s[68]||(s[68]=t("p",null,"當客户端登錄時，身份管理服務會向客户端提供一個 JWT。然後，客户端可以使用這個令牌向 API 發出請求，API 收到請求後，從服務器讀取公鑰或私密信息來驗證這個令牌。",-1)),t("p",null,[s[20]||(s[20]=l("有一些現有的庫，可以幫助我們對令牌進行驗證，包括 ",-1)),e(n,{href:"https://github.com/auth0/node-jsonwebtoken"},{default:i(()=>[...s[18]||(s[18]=[l("jsonwebtoken",-1)])]),_:1}),s[21]||(s[21]=l("。關於 JWT 的更多信息，以及各種語言中對其的支持庫，請查看 ",-1)),e(n,{href:"https://jwt.io"},{default:i(()=>[...s[19]||(s[19]=[l("JWT.io",-1)])]),_:1}),s[22]||(s[22]=l("。",-1))]),s[69]||(s[69]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import jwt from &#39;jsonwebtoken&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export default function (req, res, next) {</span></span>
<span class="line"><span>    // req.headers.authorization Bearer token</span></span>
<span class="line"><span>    const token = extractToken(req)</span></span>
<span class="line"><span>    jwt.verify(token, SECRET, { algorithms: [&#39;HS256&#39;] }, (err, decoded) =&gt; {</span></span>
<span class="line"><span>        if (err) { next(err) }</span></span>
<span class="line"><span>        req.session = decoded</span></span>
<span class="line"><span>        next()</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="_4、授權與作用域" tabindex="-1">4、授權與作用域 <a class="header-anchor" href="#_4、授權與作用域" aria-label="Permalink to “4、授權與作用域”">​</a></h4><p>認證（或身份驗證）很重要，但授權同樣很重要。也就是説，經過驗證的客户端是否有權限讓服務器執行某個請求呢？這就是作用域的價值所在。當身份管理服務器對客户端進行身份認證，且創建 JWT 令牌時，身份管理服務會給當前客户提供一個作用域，這個作用域將會決定當前經過驗證的客户的 API 請求能否被服務器執行。這樣也就免去了服務器對訪問控制列表的一些不必要的查詢。</p><p>作用域是一個文本塊（通常以空格分隔），用於描述一個 API 端點的訪問能力。一般來説，作用域被分為資源與動作。這種模式對 REST/JSON API 很有效，因為它們有相似的 <code>RESOURCE:ACTION</code> 結構。（例如，<code>ARTICLE:WRITE</code> 或 <code>ARTICLE:READ</code>，其中 <code>ARTICLE</code> 是資源，<code>READ</code> 和 <code>WRITE</code> 是動作）。</p><p>作用域的劃分讓我們的 API 能夠專注於功能的實現，而不是去考慮各種角色和用户。身份訪問管理服務可以將不同的角色和用户分配不同的權限範圍，然後再將這些不同的作用域提供給不同的 JWT 驗證中的客户。</p><h4 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h4><p>當我們開發和部署 API 時，安全應該一直是最重要的要求之一。雖然安全性是一個比較寬泛的話題，但如果能解決上面四個方面的問題，這對於你的 API 來説，在生產環境中將會表現得更好。</p><h3 id="文檔" tabindex="-1">文檔 <a class="header-anchor" href="#文檔" aria-label="Permalink to “文檔”">​</a></h3><p><em>有什麼能比沒有文檔更糟糕？過期的文檔。</em></p><p>開發者對文檔真的是又愛又恨。儘管如此，文檔仍然是 API 定義是否完善的一個關鍵部分。開發者需要從文檔中知道如何使用這些 API，且你創建的文檔對於開發者如何更好地使用 API 也有着非常巨大的作用。</p><p>創建 API 文檔，我們需要關注下面三個方面：</p><ol><li>開發者入門文檔（自述文件/基本介紹）</li><li>技術參考（規範/説明書）</li><li>使用方法（入門和其他指南）</li></ol><h4 id="_1、入門文檔" tabindex="-1">1、入門文檔 <a class="header-anchor" href="#_1、入門文檔" aria-label="Permalink to “1、入門文檔”">​</a></h4><p>在構建 API 服務的時候，你需要明確一些事情，比如：這個 API 是做什麼的？如何建立開發者環境？如何測試該服務？如何提交問題？如何部署它？</p><p>通常我們可以通過自述（<code>README</code>）文件來回答上面的這些問題，自述文件一般放在你的代碼庫中，用於為開發者提供使用你項目的最基本的起點和説明。</p><p>自述文件應該包含：</p><ul><li>API 的描述</li><li>技術參考與指南的鏈接</li><li>如何以開發者的身份設置你的項目</li><li>如何測試這個項目</li><li>如何部署這個項目</li><li>依賴管理</li><li>代碼貢獻指南</li><li>行為準則</li><li>許可證</li><li>致謝</li></ul><p>你的自述文件應該簡明扼要；你不必解釋每一個方面，但要提供足夠的信息，以便開發者在熟悉你的項目後可以進一步深入研究。</p><h4 id="_2、技術參考" tabindex="-1">2、技術參考 <a class="header-anchor" href="#_2、技術參考" aria-label="Permalink to “2、技術參考”">​</a></h4><p>在 REST/JSON API 中, 每一個具體的<ruby>端點<rt>endpoint</rt></ruby>都對應一個特定的功能，都需要一個具體的説明文檔，這非常重要。文檔中會定義 API 的描述，輸入和可能的輸出，併為各種客户端提供使用示例。</p>`,20)),t("p",null,[e(n,{href:"https://spec.openapis.org/oas/v3.1.0"},{default:i(()=>[...s[23]||(s[23]=[l("OpenAPI",-1)])]),_:1}),s[24]||(s[24]=l(" 是一個創建 REST/JSON 文檔的標準, 它可以指導你完成編寫 API 文檔所需的各種細節。OpenAPI 還可以為你的 API 生成演示文檔。",-1))]),s[70]||(s[70]=r('<h4 id="_3、使用方法" tabindex="-1">3、使用方法 <a class="header-anchor" href="#_3、使用方法" aria-label="Permalink to “3、使用方法”">​</a></h4><p>對於 API 的用户來説，僅僅只有技術説明是不夠的。他們還需要知道如何在一些特定的情況和場景下來使用這些 API，而大多數的潛在用户可能希望通過你的 API 來解決他們所遇到的問題。</p><p>向用户介紹 API 的一個好的方法是利用一個“開始”頁面。“開始”頁面可以通過一個簡單的用例引導用户，讓他們迅速瞭解你的 API 能給他們能帶來的益處。</p><h4 id="總結-1" tabindex="-1">總結 <a class="header-anchor" href="#總結-1" aria-label="Permalink to “總結”">​</a></h4><p>對於任何完善的 API，文檔都是一個很關鍵的組成部分。當你在創建文檔時，你需要關注 API 文檔中的如何入門、技術參考以及如何快速開始等三個方面，這樣你的 API 才算是一個完善的 API。</p><h3 id="驗證" tabindex="-1">驗證 <a class="header-anchor" href="#驗證" aria-label="Permalink to “驗證”">​</a></h3><p>API 開發過程中經常被忽視的一個點就是驗證。它是一個驗證來自外部來源的輸入的過程。這些來源可以是客户端發送過來的 JSON 數據，或者是你請求別人的服務收到的響應數據。我們不僅僅要檢查這些數據的類型，還要確保這些數據確實是我們要的數據，這樣可以消除很多潛在的問題。瞭解你的邊界以及你能控制的和不能控制的東西，對於 API 的數據驗證來説是一個很重要的方面。</p><p>最好的策略是在進入數據邏輯處理之前，在你能控制的邊界的邊緣處進行數據的驗證。當客户端向你的 API 發送數據時，你需要對該數據做出任何處理之前應用你的驗證，比如：確保 Email 是真實的郵件地址、日期數據有正確的格式、字符串符合長度要求。</p><p>這種簡單的檢查可以為你的應用增加安全性和一致性。還有，當你從某個服務接收數據時，比如資料庫或緩存，你需要重新驗證這些數據，以確保返回的結果符合你的數據檢查。</p>',9)),t("p",null,[s[31]||(s[31]=l("你可以自己手寫這些校驗邏輯，當然也可以用像 ",-1)),e(n,{href:"https://lodash.com"},{default:i(()=>[...s[25]||(s[25]=[l("Lodash",-1)])]),_:1}),s[32]||(s[32]=l(" 或 ",-1)),e(n,{href:"https://ramdajs.com/"},{default:i(()=>[...s[26]||(s[26]=[l("Ramda",-1)])]),_:1}),s[33]||(s[33]=l(" 這樣的函數庫，它們對於一些小的數據對象非常有用。像 ",-1)),e(n,{href:"https://joi.dev/"},{default:i(()=>[...s[27]||(s[27]=[l("Joi",-1)])]),_:1}),s[34]||(s[34]=l("、",-1)),e(n,{href:"https://github.com/jquense/yup"},{default:i(()=>[...s[28]||(s[28]=[l("Yup",-1)])]),_:1}),s[35]||(s[35]=l(" 或 ",-1)),e(n,{href:"https://github.com/colinhacks/zod/tree/v3"},{default:i(()=>[...s[29]||(s[29]=[l("Zod",-1)])]),_:1}),s[36]||(s[36]=l(" 這樣的驗證庫效果會更好，因為它們包含了一些常見的驗證方法，可以節省你的時間和精力。除此，它們還能創建一個可讀性強的模式。如果你需要看看與語言無關的東西，請看 ",-1)),e(n,{href:"https://json-schema.org/"},{default:i(()=>[...s[30]||(s[30]=[l("JSON Schema",-1)])]),_:1}),s[37]||(s[37]=l("。",-1))]),s[71]||(s[71]=r('<h4 id="總結-2" tabindex="-1">總結 <a class="header-anchor" href="#總結-2" aria-label="Permalink to “總結”">​</a></h4><p>數據驗證雖然並不顯眼和突出（LCTT 譯註：跟 API 的功能實現以及其他幾個方面比），但它可以幫你節省大量的時間。如果不做驗證，這些時間將可能被用於故障排除和編寫數據遷移腳本。真的不要相信你的客户端會發送乾淨的數據給你，也不要讓驗證不通過的數據滲入到你的業務邏輯或持久數據存儲中去。花點時間驗證你的 API 收到的數據和請求到的響應數據，雖然在前期你可能會感到一些挫折和不適，但這總比你在後期花大量時間去做各種數據收緊管制、故障排除等要容易得多。</p><h3 id="測試" tabindex="-1">測試 <a class="header-anchor" href="#測試" aria-label="Permalink to “測試”">​</a></h3><p>測試是軟件開發中的最佳實踐，它應該是最主要的非功能性的要求。對於包括 API 在內的任何項目，確定測試策略都是一個挑戰，因為你自始至終都要掌握各種約束，以便相應的來制定你的測試策略。</p><p><ruby>集成測試<rt>Integration testing</rt></ruby>是測試 API 的最有效的方法之一。在集成測試模式中，開發團隊會創建一個測試集用來覆蓋應用流程中的某些部分，從一個點到另一個點。一個好的集成測試流程包括測試 API 的入口點以及模擬請求到服務端的響應。搞定這兩點，你就覆蓋了整個邏輯，包括從 API 請求的開始到模擬服務器的響應，並返回數據給 API。</p><p>雖然使用的是模擬，但這種方法讓能我們專注於代碼邏輯層，而不需要去依賴後端服務和展示邏輯來進行測試。沒有依賴的測試會更加可靠、更容易實現自動化，且更容易被接入持續集成管道流。</p>',6)),t("p",null,[s[41]||(s[41]=l("集成測試的實施中，我會用 ",-1)),e(n,{href:"https://github.com/substack/tape"},{default:i(()=>[...s[38]||(s[38]=[l("Tape",-1)])]),_:1}),s[42]||(s[42]=l("、",-1)),e(n,{href:"https://github.com/twilson63/test-server"},{default:i(()=>[...s[39]||(s[39]=[l("Test-server",-1)])]),_:1}),s[43]||(s[43]=l(" 和 ",-1)),e(n,{href:"http://www.wheresrhys.co.uk/fetch-mock/"},{default:i(()=>[...s[40]||(s[40]=[l("Fetch-mock",-1)])]),_:1}),s[44]||(s[44]=l("。這些庫讓我們能夠從 API 的請求到數據的響應進行隔離測試，使用 Fetch-mock 還可以將出站請求捕獲到持久層。",-1))]),s[72]||(s[72]=t("h4",{id:"總結-3",tabindex:"-1"},[l("總結 "),t("a",{class:"header-anchor",href:"#總結-3","aria-label":"Permalink to “總結”"},"​")],-1)),s[73]||(s[73]=t("p",null,"雖然其他的各種測試和類型檢查對 API 也都有很好的益處，但集成測試在流程效率、構建和管理時間方面卻有着更大的優勢。使用 Fetch-mock 這樣的工具，可以在服務邊界提供一個乾淨的模擬場景。",-1)),s[74]||(s[74]=t("h3",{id:"專注於基礎",tabindex:"-1"},[l("專注於基礎 "),t("a",{class:"header-anchor",href:"#專注於基礎","aria-label":"Permalink to “專注於基礎”"},"​")],-1)),s[75]||(s[75]=t("p",null,"不管是設計和構建應用程序還是 API，都要確保包含上面的四個基本要素。它們並不是我們唯一需要考慮的非功能性需求，其他的還包括應用監控、日誌和 API 管理等。即便如此，安全、文檔、驗證和測試這四個基本點，對於構建任何使用場景下的完善 API 都是至關重要的關注點。",-1)),s[76]||(s[76]=t("hr",null,null,-1)),t("p",null,[s[46]||(s[46]=l("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/successful-apis"},{default:i(()=>[...s[45]||(s[45]=[l("https://opensource.com/article/21/5/successful-apis",-1)])]),_:1})]),t("p",null,[s[51]||(s[51]=l("作者：",-1)),e(n,{href:"https://opensource.com/users/tomwillson4014"},{default:i(()=>[...s[47]||(s[47]=[l("Tom Wilson",-1)])]),_:1}),s[52]||(s[52]=l(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[48]||(s[48]=[l("lujun9972",-1)])]),_:1}),s[53]||(s[53]=l(" 譯者：",-1)),e(n,{href:"https://github.com/ywxgod"},{default:i(()=>[...s[49]||(s[49]=[l("ywxgod",-1)])]),_:1}),s[54]||(s[54]=l(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[50]||(s[50]=[l("wxy",-1)])]),_:1})]),t("p",null,[s[57]||(s[57]=l("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[55]||(s[55]=[l("LCTT",-1)])]),_:1}),s[58]||(s[58]=l(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[56]||(s[56]=[l("Linux中國",-1)])]),_:1}),s[59]||(s[59]=l(" 榮譽推出",-1))])])}const C=a(u,[["render",P]]);export{k as __pageData,C as default};
